package com.aaliyun.leadnews.article.service;
import com.aaliyun.leadnews.article.config.MinioProperties;import io.minio.*;import java.io.*;import java.nio.charset.StandardCharsets;import org.springframework.stereotype.Component;
@Component public class ArticleObjectStorage{private final MinioClient minio;private final MinioProperties p;public ArticleObjectStorage(MinioClient m,MinioProperties p){minio=m;this.p=p;}
 public String key(long id){return "article/"+id+"/index.html";}public void putHtml(String key,String html){byte[] b=html.getBytes(StandardCharsets.UTF_8);try{ensureBucket();minio.putObject(PutObjectArgs.builder().bucket(p.bucket()).object(key).stream(new ByteArrayInputStream(b),b.length,-1).contentType("text/html; charset=utf-8").build());}catch(Exception e){throw new IllegalStateException("MinIO HTML upload failed",e);}}
 public StoredObject get(String key){try{StatObjectResponse s=minio.statObject(StatObjectArgs.builder().bucket(p.bucket()).object(key).build());try(InputStream in=minio.getObject(GetObjectArgs.builder().bucket(p.bucket()).object(key).build())){return new StoredObject(in.readAllBytes(),s.etag(),s.lastModified().toInstant().toEpochMilli());}}catch(Exception e){throw new IllegalStateException("MinIO object read failed",e);}}
 public String publicUrl(String key){return p.publicEndpoint()+"/"+p.bucket()+"/"+key;}private void ensureBucket()throws Exception{if(!minio.bucketExists(BucketExistsArgs.builder().bucket(p.bucket()).build()))minio.makeBucket(MakeBucketArgs.builder().bucket(p.bucket()).build());}public record StoredObject(byte[] bytes,String etag,long lastModified){}
}
